// Run with: node --test web/test
// Cross-implementation vectors for the stagenet escrow wire grammar. The
// expected bytes come from `cargo run -p escrow-format --example vectors`;
// this proves the browser builder, decoder, and replay mirror agree with Rust
// without a wallet or RPC.
import test from 'node:test';
import assert from 'node:assert/strict';

let escrow = null;
let ed = null;
let hex = null;
try {
  escrow = await import('../src/domain/escrow.ts');
  ed = await import('@noble/curves/ed25519.js');
  hex = await import('@noble/hashes/utils.js');
} catch {
  escrow = null;
}

const skip = { skip: escrow ? false : 'node_modules missing (@noble crypto); run npm ci in web/' };
const PRIV = '2a'.repeat(32);
const PUB = '197f6b23e16c8532c6abc838facd5ea789be0c76b2920334039bfa8b3d368d61';
const ORDER = 'ab'.repeat(16);
const NONCE = 'cd'.repeat(16);
const ESCROW_ADDRESS = '5StagenetEscrow';
const AMOUNT = 1_234_000_000_000n;

// One envelope per domain (generated by escrow-format/examples/vectors.rs).
const OPEN = '';
const JOIN = '';
const COMMIT = '';
const FUNDED = '';
const RELEASE = '';
const APPROVE = '';
const DISPUTE = '';
const RESOLVE = '';
const CANCEL = '';
const SUBMITTED = '';

// Complete three-party happy path, in relay acceptance order.
const LIFECYCLE = [
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
  '',
];

test('escrow signer key matches the Rust vector', skip, () => {
  assert.equal(hex.bytesToHex(ed.ed25519.getPublicKey(hex.hexToBytes(PRIV))), PUB);
});

test('open envelope matches the Rust vector', skip, () => {
  const signed = escrow.signEnvelope(
    escrow.openUnsigned(PUB, 20400, 7, ORDER, NONCE, '11'.repeat(32), '22'.repeat(32), AMOUNT, 'XMR'),
    PRIV,
  );
  assert.equal(hex.bytesToHex(signed), OPEN);
  const parsed = escrow.verifyEnvelope(signed);
  assert.equal(parsed.domain, escrow.OPEN_DOMAIN);
  assert.equal(parsed.actor, PUB);
  assert.equal(parsed.day, 20400n);
  assert.equal(parsed.seq, 7n);
});

test('join and release envelopes match the Rust vectors', skip, () => {
  const join = escrow.signEnvelope(
    escrow.joinUnsigned(PUB, 20400, 8, ORDER, NONCE, 0, new TextEncoder().encode('MultisigxV2ABC')),
    PRIV,
  );
  assert.equal(hex.bytesToHex(join), JOIN);
  const release = escrow.signEnvelope(
    escrow.releaseUnsigned(PUB, 20400, 9, ORDER, NONCE, '56Payout', AMOUNT, '03'.repeat(32), '04'.repeat(32)),
    PRIV,
  );
  assert.equal(hex.bytesToHex(release), RELEASE);
  const bad = release.slice();
  bad[bad.length - 1] ^= 1;
  assert.throws(() => escrow.verifyEnvelope(bad), /signature does not verify/);
});

test('escrow constants reject drift at the boundary', skip, () => {
  assert.equal(escrow.MAX_ESCROW_ATOMIC, 10_000_000_000_000);
  assert.equal(escrow.XMR_ATOMIC_UNITS, 1_000_000_000_000);
  assert.equal(escrow.MAX_BLOB_BYTES, 16_384);
  assert.throws(
    () => escrow.openUnsigned(PUB, 1, 0, ORDER, NONCE, '11'.repeat(32), '22'.repeat(32), 10_000_000_000_001n, 'XMR'),
    /reference cap/,
  );
  assert.throws(
    () => escrow.openUnsigned(PUB, 1, 0, ORDER, NONCE, '11'.repeat(32), '22'.repeat(32), 1n, 'usd'),
    /currency/,
  );
});

test('decoder accepts every Rust domain vector and rejects tampering', skip, () => {
  const cases = [
    [OPEN, escrow.OPEN_DOMAIN, (d) => d.amount === AMOUNT && d.currency === 'XMR'],
    [JOIN, escrow.JOIN_DOMAIN, (d) => d.role === 0 && new TextDecoder().decode(d.blob) === 'MultisigxV2ABC'],
    [COMMIT, escrow.COMMIT_DOMAIN, (d) => d.round === 3 && d.address === ESCROW_ADDRESS],
    [FUNDED, escrow.FUNDED_DOMAIN, (d) => d.amount === AMOUNT && new TextDecoder().decode(d.proof) === 'proof'],
    [RELEASE, escrow.RELEASE_DOMAIN, (d) => d.payout === '56Payout' && d.txsetHash === '04'.repeat(32)],
    [APPROVE, escrow.APPROVE_DOMAIN, (d) => d.role === 0],
    [DISPUTE, escrow.DISPUTE_DOMAIN, (d) => d.reason === 1 && d.body === 'not delivered'],
    [RESOLVE, escrow.RESOLVE_DOMAIN, (d) => d.decision === 1 && d.payout === '5BuyerRefund'],
    [CANCEL, escrow.CANCEL_DOMAIN, (d) => d.reason === 0],
    [SUBMITTED, escrow.SUBMITTED_DOMAIN, (d) => d.kind === 0],
  ];
  for (const [raw, domain, check] of cases) {
    const bytes = hex.hexToBytes(raw);
    const decoded = escrow.decodeEnvelope(bytes);
    assert.equal(decoded.domain, domain);
    assert.equal(decoded.order, ORDER);
    assert.equal(decoded.nonce, NONCE);
    assert.equal(decoded.day, 20400n);
    assert.equal(check(decoded), true);
    const tampered = bytes.slice();
    tampered[60] ^= 1; // inside the signed payload
    assert.throws(() => escrow.decodeEnvelope(tampered), /signature does not verify/);
  }
});

test('transcript and funding messages match the harness derivation', skip, () => {
  const commit = escrow.decodeEnvelope(hex.hexToBytes(COMMIT));
  assert.equal(
    commit.transcriptHash,
    escrow.setupTranscriptHash(ORDER, NONCE, ESCROW_ADDRESS),
  );
  assert.equal(
    escrow.fundingProofMessage(ORDER, NONCE, AMOUNT),
    `nysiris-escrow:${ORDER}:${NONCE}:funded:${AMOUNT}`,
  );
});

test('txset description hash matches the harness canonical JSON', skip, () => {
  const desc = [{
    unlock_time: 0,
    fee: 100,
    inputs: [{ id: 'aa', amount: 500 }],
    recipients: [{ address: '5Pay', amount: 400 }],
    change: 100,
  }];
  // Reference from monero_escrow_stagenet.canonical() + sha256_bytes().
  assert.equal(
    escrow.txsetDescriptionHash(desc),
    '42c9ddd1cf0765d6d556ea545adb839deb2e8c7eb6d77cf2c21c7742e41b52a5',
  );
  // Key order in the JS object does not change the canonical digest.
  const shuffled = [{ recipients: desc[0].recipients, change: 100, fee: 100, inputs: desc[0].inputs, unlock_time: 0 }];
  assert.equal(escrow.txsetDescriptionHash(shuffled), escrow.txsetDescriptionHash(desc));
});

test('mirror rejects a zero order or nonce just like escrow-format', skip, () => {
  const zeroOrder = escrow.signEnvelope(
    escrow.openUnsigned(PUB, 20400, 0, '00'.repeat(16), NONCE, '11'.repeat(32), '22'.repeat(32), AMOUNT, 'XMR'),
    PRIV,
  );
  const zeroNonce = escrow.signEnvelope(
    escrow.openUnsigned(PUB, 20400, 0, ORDER, '00'.repeat(16), '11'.repeat(32), '22'.repeat(32), AMOUNT, 'XMR'),
    PRIV,
  );
  assert.throws(() => new escrow.EscrowMirror().applyReplay(zeroOrder), /zero order id or nonce/);
  assert.throws(() => new escrow.EscrowMirror().applyReplay(zeroNonce), /zero order id or nonce/);
});

test('u64 day survives a round trip without Number precision loss', skip, () => {
  const huge = 18_446_744_073_709_551_615n;
  const signed = escrow.signEnvelope(
    escrow.cancelUnsigned(PUB, huge, 0, ORDER, NONCE, 0),
    PRIV,
  );
  assert.equal(escrow.verifyEnvelope(signed).day, huge);
  assert.equal(escrow.decodeEnvelope(signed).day, huge);
});

test('browser replay reaches the same stage as Rust and detects relay lies', skip, () => {
  const envelopes = LIFECYCLE.map((raw) => hex.hexToBytes(raw));
  const mirror = new escrow.EscrowMirror();
  mirror.replayAll(envelopes);
  assert.equal(mirror.stage, 'released');
  assert.equal(mirror.releaseTxsetHash, '55'.repeat(32));
  assert.equal(mirror.amount, AMOUNT);

  const response = {
    session: { stage: 'released' },
    events: LIFECYCLE.map((envelope) => ({ envelope })),
  };
  assert.equal(escrow.replayRelayResponse(response).stage, 'released');
  assert.throws(
    () => escrow.replayRelayResponse({ ...response, session: { stage: 'proposed' } }),
    /does not match the replayed signed log/,
  );
  const tampered = [...LIFECYCLE];
  const bytes = hex.hexToBytes(tampered[9]);
  bytes[80] ^= 1;
  tampered[9] = hex.bytesToHex(bytes);
  assert.throws(
    () => escrow.replayRelayResponse({ ...response, events: tampered.map((envelope) => ({ envelope })) }),
    /signature does not verify/,
  );

  // A replayed log cannot be extended after release, and funding hints stay pure.
  const closed = new escrow.EscrowMirror();
  closed.replayAll(envelopes);
  assert.throws(() => closed.applyReplay(envelopes[0]), /session is closed/);
  assert.equal(closed.fundingExpired(20400n), false);
});
